package br.com.helptech.v3;
import android.app.*;import android.os.*;import android.content.*;import android.view.*;import android.widget.*;import android.media.*;
public class AlarmActivity extends Activity{
 MediaPlayer player;String id,client,service,address;
 @Override public void onCreate(Bundle b){super.onCreate(b);if(Build.VERSION.SDK_INT>=27){setShowWhenLocked(true);setTurnScreenOn(true);}getWindow().addFlags( WindowManager.LayoutParams.FLAG_KEEP_SCREEN_ON|WindowManager.LayoutParams.FLAG_DISMISS_KEYGUARD);id=getIntent().getStringExtra("id");client=getIntent().getStringExtra("client");service=getIntent().getStringExtra("service");address=getIntent().getStringExtra("address");LinearLayout root=new LinearLayout(this);root.setOrientation(1);root.setPadding(30,60,30,30);root.setBackgroundColor(0xff071b37);TextView title=new TextView(this);title.setText("🚨 GESTÃO HELP-TECH\nSERVIÇO AGENDADO");title.setTextSize(24);title.setTextColor(-1);root.addView(title);TextView info=new TextView(this);info.setText("\nCliente: "+client+"\nServiço: "+service+"\nEndereço: "+address+"\n");info.setTextSize(20);info.setTextColor(-1);root.addView(info);Button snooze=new Button(this);snooze.setText("PRORROGAR 30 MINUTOS");root.addView(snooze);Button done=new Button(this);done.setText("MARCAR CHAMADO COMO ATENDIDO");root.addView(done);setContentView(root);snooze.setOnClickListener(v->{AlarmReceiver.set(this,id,client,service,address,System.currentTimeMillis()+30*60*1000L);((android.app.NotificationManager)getSystemService(NOTIFICATION_SERVICE)).cancel(AlarmReceiver.request(id));stopSound();finish();});done.setOnClickListener(v->{getSharedPreferences("attended",0).edit().putBoolean(id,true).apply();AlarmReceiver.cancel(this,id);stopSound();Intent main=new Intent(this,MainActivity.class);main.putExtra("attended_id",id);main.addFlags(Intent.FLAG_ACTIVITY_CLEAR_TOP|Intent.FLAG_ACTIVITY_SINGLE_TOP);startActivity(main);finish();});try{player=MediaPlayer.create(this,android.provider.Settings.System.DEFAULT_ALARM_ALERT_URI);if(player!=null){player.setAudioAttributes(new AudioAttributes.Builder().setUsage(AudioAttributes.USAGE_ALARM).build());player.setLooping(true);player.start();}}catch(Exception e){} }
 void stopSound(){if(player!=null){try{player.stop();player.release();}catch(Exception e){}player=null;}}
 @Override public void onDestroy(){stopSound();super.onDestroy();}
 @Override public void onBackPressed(){/* A tela permanece até uma das duas ações */}
}
